-- month-holiness-03
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что вы ежедневно выполняете практики, которые мы определили на предыдущих занятиях, в результате чего вы уже без затруднений настраиваетесь на поток седьмой чакры и удерживаете этот поток. А значит мы можем разнообразить и углубить практику. Длительность этого урока - 1.5 часа. Пройдите его на одном дыхании, не прерываясь.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly">Урок 3</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что вы ежедневно выполняете практики, которые мы определили на предыдущих занятиях, в результате чего вы уже без затруднений настраиваетесь на поток седьмой чакры и удерживаете этот поток. А значит мы можем разнообразить и углубить практику. Длительность этого урока - 1.5 часа. Пройдите его на одном дыхании, не прерываясь.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly">Урок 3</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что вы ежедневно выполняете практики, которые мы определили на предыдущих занятиях, в результате чего вы уже без затруднений настраиваетесь на поток седьмой чакры и удерживаете этот поток. А значит мы можем разнообразить и углубить практику. Длительность этого урока - 1.5 часа. Пройдите его на одном дыхании, не прерываясь.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly\">Урок 3</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
