-- month-holiness-04
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве святости, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию седьмой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly">Открыть доп. урок 1</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве святости, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию седьмой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly">Открыть доп. урок 1</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве святости, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию седьмой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly\">Открыть доп. урок 1</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='5a095cb3-1c0b-57e6-b06a-16d4ed722e73';

-- month-holiness-05
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца святости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока. Мы направим внимание на Бхакти йогу, подготовив себя к её восприятию настолько, насколько это возможно за одно практическое занятие. Длительность урока - 2.3 часа.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly">Урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца святости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока. Мы направим внимание на Бхакти йогу, подготовив себя к её восприятию настолько, насколько это возможно за одно практическое занятие. Длительность урока - 2.3 часа.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly">Урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-05-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца святости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока. Мы направим внимание на Бхакти йогу, подготовив себя к её восприятию настолько, насколько это возможно за одно практическое занятие. Длительность урока - 2.3 часа.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly\">Урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='2d7cb280-d7c1-545e-8b15-ba3264929461';

-- month-holiness-06
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию седьмой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly">Открыть доп. урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию седьмой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly">Открыть доп. урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-06-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию седьмой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly\">Открыть доп. урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='4d843a2a-5915-55dd-8993-f2025c8d55b0';

-- month-holiness-07
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию седьмой чакры. И мы выполним практику, финализирующую наши действия в течение месяца. Длительность урока - 2 часа.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly">Урок 5</a></p><p></p><p>И, так как месяц святости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизациюмужско-женских отношений, и немножечко прикоснёмся к тантре. Чтобы ознакомиться с предложением и записаться, перейдите по ссылке - <a href="https://zamkovoi.yoga/mmz/">https://zamkovoi.yoga/mmz/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png" alt="Месяц святости" width="504" height="159" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию седьмой чакры. И мы выполним практику, финализирующую наши действия в течение месяца. Длительность урока - 2 часа.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly">Урок 5</a></p><p></p><p>И, так как месяц святости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизациюмужско-женских отношений, и немножечко прикоснёмся к тантре. Чтобы ознакомиться с предложением и записаться, перейдите по ссылке - <a href="https://zamkovoi.yoga/mmz/">https://zamkovoi.yoga/mmz/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-holiness/m7_email-c7a920a26246.png","alt":"Месяц святости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":533,"naturalHeight":168},{"id":"month-holiness-07-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию седьмой чакры. И мы выполним практику, финализирующую наши действия в течение месяца. Длительность урока - 2 часа.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#bf56a5;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#bf56a5;mso-line-height-rule:exactly\">Урок 5</a></p><p></p><p>И, так как месяц святости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизациюмужско-женских отношений, и немножечко прикоснёмся к тантре. Чтобы ознакомиться с предложением и записаться, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/mmz/\">https://zamkovoi.yoga/mmz/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='2c19d6e9-be1a-5035-9af5-8d02e4a8a31b';

